/// <summary>
/// submitExceptions' request: unexpected items and verified-empty locations of one submission.
/// SubmissionId is the same idempotency key the counts were sent with.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountExceptionsRequest
{
    DataAreaId      dataAreaId;
    InventJournalId journalId;
    str             claimToken;
    str             submissionId;
    str             userId;
    str             deviceId;
    str             exceptionsJson;
    str             emptyLocationsJson;
    str             confirmationsJson;
    List            exceptions;
    List            emptyLocations;
    List            confirmations;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
