/// <summary>
/// Unexpected items. Read from ExceptionsJson. Not a data member itself: a list of a custom
/// class does not bind on the way in (JObject cast failure - see
/// HSMobileOpsPostRequest.parmLinesJson).
/// </summary>
public List parmExceptions(List _value = exceptions)
{
    Newtonsoft.Json.Linq.JArray  jArray;
    Newtonsoft.Json.Linq.JObject jRow;
    HSMobileOpsCountExceptionRow row;
    int                          rowCount;
    int                          i;

    exceptions = _value;
    if (!exceptions && exceptionsJson)
    {
        exceptions = new List(Types::Class);
        jArray = HSMobileOpsCountExceptionsRequest::jsonArray(exceptionsJson);
        rowCount = jArray == null ? 0 : jArray.get_Count();
        for (i = 0; i < rowCount; i++)
        {
            jRow = jArray.get_Item(i);
            if (jRow == null)
            {
                continue;
            }
            row = new HSMobileOpsCountExceptionRow();
            row.parmClientId(HSMobileOpsCountExceptionsRequest::jsonStr(jRow, 'ClientId'));
            row.parmItemNumber(HSMobileOpsCountExceptionsRequest::jsonStr(jRow, 'ItemNumber'));
            row.parmLocationId(HSMobileOpsCountExceptionsRequest::jsonStr(jRow, 'LocationId'));
            row.parmQuantity(HSMobileOpsCountExceptionsRequest::jsonNum(jRow, 'Quantity'));
            row.parmBatchId(HSMobileOpsCountExceptionsRequest::jsonStr(jRow, 'BatchId'));
            row.parmSerialId(HSMobileOpsCountExceptionsRequest::jsonStr(jRow, 'SerialId'));
            row.parmNote(HSMobileOpsCountExceptionsRequest::jsonStr(jRow, 'Note'));
            row.parmCapturedBy(HSMobileOpsCountExceptionsRequest::jsonStr(jRow, 'CapturedBy'));
            row.parmCapturedAtUtc(HSMobileOpsCountExceptionsRequest::jsonStr(jRow, 'CapturedAtUtc'));
            exceptions.addEnd(row);
        }
    }
    return exceptions;
}

/// <summary>
/// Unexpected items as a JSON array of HSMobileOpsCountExceptionRow's members.
/// </summary>
[DataMemberAttribute('ExceptionsJson')]
public str parmExceptionsJson(str _value = exceptionsJson)
{
    exceptionsJson = _value;
    return exceptionsJson;
}

