/// <summary>
/// Verify-only lines (e.g. in transit) the counter confirmed instead of counting. Read from
/// ConfirmationsJson. Not a data member itself: a list of a custom class does not bind on the
/// way in (JObject cast failure - see HSMobileOpsPostRequest.parmLinesJson).
/// </summary>
public List parmConfirmations(List _value = confirmations)
{
    Newtonsoft.Json.Linq.JArray     jArray;
    Newtonsoft.Json.Linq.JObject    jRow;
    HSMobileOpsCountConfirmationRow row;
    int                             rowCount;
    int                             i;

    confirmations = _value;
    if (!confirmations && confirmationsJson)
    {
        confirmations = new List(Types::Class);
        jArray = HSMobileOpsCountExceptionsRequest::jsonArray(confirmationsJson);
        rowCount = jArray == null ? 0 : jArray.get_Count();
        for (i = 0; i < rowCount; i++)
        {
            jRow = jArray.get_Item(i);
            if (jRow == null)
